/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeRetailSalesTableTmpPriceDiscountData extends GUPPricingAttributeRetailSalesTable implements GUPIPricingAttribute
{
}

