public str getName()
{
    return fieldPName(RetailSalesTable, TmpPriceDiscountData);
}

    public Set getAllowedValues()
    {
        RetailSalesTable    retailSalesTable;
        var                 ret = new Set(Types::Container);

        while select TmpPriceDiscountData from retailSalesTable
            group by TmpPriceDiscountData
        {
            ret.add(retailSalesTable.ChannelReferenceId);
        }

        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(RetailSalesTable, TmpPriceDiscountData));
        qbr.value(queryValue(_value));
    }
